package com.ecommerce.user_service.service;
import com.ecommerce.user_service.entity.UserAddress; import com.ecommerce.user_service.repository.UserAddressRepository; import jakarta.persistence.EntityNotFoundException; import java.util.List; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true) public class AddressService {private final UserAddressRepository repo; public AddressService(UserAddressRepository r){repo=r;} public List<UserAddress> list(long user){return repo.findByUserIdOrderByIdDesc(user);} @Transactional public UserAddress create(long user,String l,String a,String b,String c,String s,String p,String co,String phone,boolean sms){if(sms&&(phone==null||phone.isBlank()))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"Phone number is required for SMS updates");return repo.save(new UserAddress(user,l,a,b,c,s,p,co,phone,sms));} @Transactional public UserAddress update(long user,long id,String l,String a,String b,String c,String s,String p,String co,String phone,boolean sms){if(sms&&(phone==null||phone.isBlank()))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"Phone number is required for SMS updates");var x=find(user,id);x.update(l,a,b,c,s,p,co,phone,sms);return x;} @Transactional public void delete(long user,long id){repo.delete(find(user,id));} private UserAddress find(long user,long id){return repo.findByIdAndUserId(id,user).orElseThrow(()->new EntityNotFoundException("Address not found"));}}
